'Test Parallel wrapping.'
joblib = pytest.importorskip('joblib')
if os.getenv('MNE_FORCE_SERIAL', '').lower() in ('true', '1'):
    pytest.skip('MNE_FORCE_SERIAL is set')

def fun(x):
    return x * 2
if isinstance(n_jobs, str):
    backend, n_jobs = n_jobs.split()
    n_jobs = want_jobs = int(n_jobs)
    try:
        func = joblib.parallel_config
    except AttributeError:
        func = joblib.parallel_backend
    ctx = func(backend, n_jobs=n_jobs)
    n_jobs = None
else:
    ctx = nullcontext()
    if n_jobs is not None and n_jobs < 0:
        want_jobs = multiprocessing.cpu_count() + 1 + n_jobs
    else:
        want_jobs = 1
with ctx:
    parallel, p_fun, got_jobs = parallel_func(fun, n_jobs, verbose='debug')
assert got_jobs == want_jobs

'Test surface source space docstring.'
if src_kind == 'fwd':
    src = mne.read_source_spaces(fname_fwd)
else:
    assert src_kind == 'src'
    src = mne.read_source_spaces(fname_src)
for s in src:
    if src_kind == 'src':
        assert len(s['pinfo']) == s['nuse']
        assert_array_equal(s['patch_inds'], np.arange(s['nuse']))
    else:
        assert len(s['pinfo']) > s['nuse']
    all_pinfo = np.concatenate(s['pinfo'])
    assert_array_equal(np.sort(all_pinfo), np.arange(s['np']))
    assert len(s['patch_inds']) == s['nuse']
    assert len(s['vertno']) == s['nuse']
    assert len(s['patch_inds']) == s['nuse']
    for idx in (0, 42, 173):
        this_dense_vertex = s['vertno'][idx]
        this_vertex_represents = s['pinfo'][s['patch_inds'][idx]]
        assert len(this_vertex_represents) > 1
        for other in this_vertex_represents:
            assert s['nearest'][other] == this_dense_vertex

