        assert len(figs) == expected_n_figs

'Test t-test equivalence.'
rng = np.random.RandomState(seed)

def theirs(*a, **kw):
    f = getattr(scipy.stats, f'ttest_{kind}')
    if kind == '1samp':
        func = partial(f, popmean=0, **kwargs)
    else:
        func = partial(f, **kwargs)
    return func(*a, **kw)[0]
ours = partial(getattr(mne.stats, f'ttest_{kind}_no_p'), sigma=sigma, **kwargs)
X = rng.randn(3, 4, 5)
if kind == 'ind':
    X = [X, rng.randn(30, 4, 5)]
    got = ours(*X)
    want = theirs(*X)
else:
    got = ours(X)
    want = theirs(X)
if sigma == 0.0:
    assert_allclose(got, want, rtol=1e-07, atol=1e-06)
else:
    assert not np.allclose(got, want, rtol=1e-07, atol=1e-06)
    assert_allclose(got, want, rtol=0.2, atol=0.01)
    assert_array_less(np.abs(got), np.abs(want))

'Test equalize_bads function.'
raw, epochs, evoked = _load_data()
if inst_type == 'raw':
    insts = [raw.copy().crop(0, 1), raw.copy().crop(0, 2)]
elif inst_type == 'epochs':
    insts = [epochs.copy()[:1], epochs.copy()[:2]]
else:
    insts = [evoked.copy().crop(0, 0.1), raw.copy().crop(0, 0.2)]
with pytest.raises(ValueError, match='between 0'):
    equalize_bads(insts, interp_thresh=2.0)
bads = insts[0].copy().pick('eeg').ch_names[:3]
insts[0].info['bads'] = bads[:2]
insts[1].info['bads'] = bads[1:]
insts_ok = equalize_bads(insts, interp_thresh=interp_thresh)
if interp_thresh == 0:
    bads_ok = []
elif interp_thresh == 1:
    bads_ok = bads
else:
    bads_ok = bads[1:]
for inst in insts_ok:
    assert set(inst.info['bads']) == set(bads_ok)

'Test importing EEGLAB .set files.'
montage = read_custom_montage(montage_path)
montage.ch_names = [f'EEG {ii:03d}' for ii in range(len(montage.ch_names))]
kws = dict(reader=read_raw_eeglab, input_fname=fname)
if fname.name == 'test_raw_chanloc.set':
    with pytest.warns(RuntimeWarning, match="The data contains 'boundary' events"):
        raw0 = _test_raw_reader(**kws)
elif '_h5' in fname.name:
    raw0 = read_raw_eeglab(fname, preload=True)
else:
    raw0 = _test_raw_reader(**kws)
if fname.name == 'test_raw_chanloc.set':
    raw0.set_montage(montage, on_missing='ignore')
    raw0.crop(0, 1)
else:
    raw0.set_montage(montage)
    raw0.filter(1, None, l_trans_bandwidth='auto', filter_length='auto', phase='zero')
read_raw_kws = dict(input_fname=fname, preload=False, uint16_codec='ascii')
if fname.name == 'test_raw_chanloc.set':
    with pytest.warns(RuntimeWarning, match="The data contains 'boundary' events"):
        raw0 = read_raw_eeglab(**read_raw_kws)
        raw0.set_montage(montage, on_missing='ignore')
else:
    raw0 = read_raw_eeglab(**read_raw_kws)
    raw0.set_montage(montage)
if fname != raw_fname_chanloc:
    assert len(raw0.annotations) == 154
    assert set(raw0.annotations.description) == {'rt', 'square'}
    assert_array_equal(raw0.annotations.duration, 0.0)

